const TYPE = { video: ['video', '🎥', ['concept', 'motivate']], q: ['fun_question', '💡', ['concept', 'basic_problem']], tip: ['tip', '🧩', ['concept', 'misconception']], real: ['real_world', '🌍', ['real_world', 'summary']], game: ['game', '🎮', ['leveled_problem', 'offline_activity']], x: ['misconception', '⚠️', ['misconception', 'basic_problem']], e: ['example', '📝', ['concept', 'offline_activity']], c: ['checklist', '✅', ['next_lesson']] };
const PFX = { video: 'v', q: 'q', tip: 't', real: 'r', game: 'g', x: 'x', e: 'e', c: 'c' };
function extras(n, list) {
  const cnt = {};
  return list.map(line => {
    const p = line.split('|'); const k = p[0]; cnt[k] = (cnt[k] || 0) + 1; const [type, icon, fit] = TYPE[k];
    const id = PFX[k] + '_l' + n + '_' + cnt[k];
    if (k === 'video') return { id, type, icon, title: p[1], url: 'https://www.youtube.com/results?search_query=' + encodeURIComponent(p[2]).replace(/%20/g, '+'), description: p[3], source: '유튜브 검색 (교사 사전 확인 권장)', fit_slides: fit };
    return { id, type, icon, title: p[1], content: p[2], fit_slides: fit };
  });
}
/* 원문 문항(4택) → 기본 문제 */
function problemData(q, title, body, icon) {
  return { title, scenario: { icon: icon || '🏘️', body }, question: q.t, options: q.opts.map((t, i) => (i === q.ci ? { text: t, correct: true } : { text: t })), note: '풀이: ' + q.reason + ' → **' + q.opts[q.ci] + '**' };
}
/* 개념 장 말풍선 = 원문 말풍선, 없으면(발문 답 장) 원문 답 상자, 그것도 없으면 목록 줄 */
const say = (sl) => sl.bub || sl.answer.join(' ') || sl.items.map(nm).join(' ');
const slideText = (sl) => nm([sl.title, sl.bub, sl.note, sl.answer.join(' '), sl.items.join(' '), sl.scene.join(' ')].join(' ')).replace(/\s+/g, ' ');
/* 동기 물음 = 원문 1번 장 제목(T.ask 가 있으면 그 장) · 판 장 = 원문 5번(모든 키) */
const askSlide = (k) => SL(k, T[k].ask != null ? T[k].ask : 1);
const boardI = (k) => 5;

/* 교사 층(T 표) 「결」 0 — 차단 어휘 규칙(199차 처리) */
if (/결/.test(JSON.stringify(T))) throw new Error('T 표에 「결」: ' + JSON.stringify(T).match(/.{0,12}결.{0,12}/)[0]);

const LESSONS = {};
const keys = Object.keys(T);
if (keys.join() !== Object.keys(SRC).join()) throw new Error('키 ≠ 재료 키 ' + keys.join());
keys.forEach((key, idx) => {
  const t = T[key], s = SRC[key], n = +key.slice(-2);
  const used = t.basic.map(x => x[0]);
  const mq = s.problems[t.mis[0]];
  if (t.mis[1] === mq.ci) throw new Error(key + ' 오개념 = 정답 보기');
  if (used.indexOf(t.mis[0]) >= 0) throw new Error(key + ' 오개념 문항이 기본 문제에도');
  if (JSON.stringify(t.cv) !== JSON.stringify(s.covers)) throw new Error(key + ' 차시 ≠ 재료 ' + s.covers);
  const ask = askSlide(key); if (!/[?？]$/.test(nm(ask.title)) || ask.kind === 'board') throw new Error(key + ' 동기 장 꼴');
  /* extras 22 = 교사 표 13(tip 5·real 3·game 2·e 3) + 원문에서 9(video 1 · 기본 문제에 안 쓴 문항 5 → 더 물어보기 · 오개념 문항의 나머지 틀린 보기 2 → 헷갈리는 생각 · 다음 차시 준비 1) */
  const auto = ['video|' + s.title + ' 영상|초등 4학년 2학기 사회 ' + s.title.replace(/[「」\[\]]/g, '') + '|' + plain(ask.title) + ' 장면.']
    .concat(s.problems.map((q, i) => i).filter(i => used.indexOf(i) < 0).map((i, j) => 'q|더 물어보기 ' + (j + 1) + '|' + s.problems[i].t))
    .concat(mq.opts.map((o, i) => i).filter(i => i !== mq.ci && i !== t.mis[1]).map((i, j) => 'x|헷갈리는 생각 ' + (j + 1) + '|' + mq.opts[i] + ' — 알맞지 않아요.'))
    .concat(['c|' + t.prep]);
  const ex = extras(n, auto.concat(t.ex)); const id = (k, i) => ex.filter(e => e.id.startsWith(PFX[k] + '_l' + n + '_'))[i - 1].id;
  if (ex.length !== 22) throw new Error(key + ' extras ' + ex.length);
  const prevExit = idx === 0 ? PREV_EXIT : T[keys[idx - 1]].exit;
  const slides = [];
  const add = (block, stage, data, sug, tn, src) => { const sl = { id: 's' + String(slides.length + 1).padStart(2, '0'), stage, block, data }; if (src != null) sl.src = src; if (tn) data.tnote = tn; sl.suggested_extras = sug || []; slides.push(sl); };
  add('cover', '도입', { title: s.title + '\n' + t.cover[0], emoji: t.cover[1] }, [id('video', 1)]);
  add('review', '도입', { title: '지난 시간엔 무엇을 했나요?', content: t.review, items: prevExit.map(x => ({ q: x.q, a: x.a })), from: idx === 0 ? PREV_KEY : keys[idx - 1] }, [id('q', 1)]);
  add('motivate', '도입', { scene_title: t.mot.t, kids: t.mot.kids.map(([face, label]) => ({ face, label })), question: plain(ask.title), img: 'assets/photo/social/' + t.mot.img + '.jpg' }, [id('q', 2), id('real', 1)], t.mot.tn, ask.i);
  const csug = [[id('e', 1)], [id('tip', 1)], [id('e', 2), id('tip', 2)], [id('q', 3)]];
  t.con.forEach(([si, fig, tn, lead], i) => {
    const src = SL(key, si); const board = fig === 'board'; if (board !== (si === boardI(key))) throw new Error(key + ' 판 장 ' + si);
    if (!board) { const txt = slideText(src); fig.items.forEach(it => { if (txt.indexOf(nm(it.name)) < 0) throw new Error(key + ' s' + si + ' 카드 이름 원문에 없음: ' + it.name); if (it.kind && txt.indexOf(nm(it.kind)) < 0) throw new Error(key + ' s' + si + ' 카드 글 원문에 없음: ' + it.kind); }); }
    add('concept', '전개', { fig: board ? BOARD[key]() : fig, title: nm(src.title), content: board ? lead : say(src) }, csug[i], tn, si);
  });
  add('misconception', '전개', { title: '헷갈리기 쉬운 생각', label: '자주 하는 생각', wrong: mq.opts[t.mis[1]], right: mq.opts[mq.ci], hint: t.mis[2] }, [id('x', 1), id('x', 2)], t.mis[3], 'p' + t.mis[0]);
  const bsug = [[id('tip', 3)], [id('e', 3)], [id('q', 4)]];
  t.basic.forEach(([pi, body, icon], i) => add('basic_problem', '기본문제', problemData(s.problems[pi], '기본 문제 ' + '①②③'[i], body, icon), bsug[i], null, 'p' + pi));
  add('leveled_problem', '기본문제', { title: '수준을 골라 풀어요', levels: t.lev }, [id('q', 5), id('game', 1)], t.levTn);
  add('offline_activity', '응용문제', { title: t.act.t, type: t.act.type, goal: t.act.goal, steps: t.act.steps, solo: t.act.solo, materials: t.act.mats, minutes: t.act.min }, [id('game', 2), id('tip', 4)], t.act.tn);
  add('real_world', '응용문제', { title: t.real[0], scenario: { icon: t.real[1], body: t.real[2] }, content: t.real[3] }, [id('real', 2), id('real', 3)]);
  add('advanced_problem', '응용문제', { title: '생각을 넓혀요', context: t.adv[0], challenge: t.adv[1], note: t.adv[2] }, [id('tip', 5)], t.adv[3]);
  add('exit_ticket', '정리', { title: '오늘 확인해요', items: t.exit, self: ['오늘 배운 것을 혼자 설명할 수 있어요', '조금 헷갈려요', '다시 배우고 싶어요'] }, []);
  add('summary', '정리', { title: '오늘 배운 것', points: t.story ? s.summary.concat(t.story) : s.summary, arrows: t.arrows }, [id('real', 1)]);
  add('self_assessment', '정리', { title: '스스로 점검해요', items: ['📚 지식·이해 — ' + s.self[0], '🔧 과정·기능 — ' + s.self[1], '💛 가치·태도 — ' + s.self[2]], prompts: ['스스로 돌아봐요 — 체크가 잘 안 되는 곳은 다시 살펴봐도 좋아요.'] }, [id('e', 3)]);
  const last = idx === keys.length - 1;
  if (last && nm(s.next)) throw new Error(key + ' 마지막 차시인데 원문 next 있음');
  add('next_lesson', '정리', { title: last ? '이 단원을 마쳐요' : '다음 시간엔', preview: last ? nm(s.end_note) : nm(s.next), emoji: t.nextIcon }, [id('c', 1)]);
  const cv = t.cv, a = cv[0], c2 = cv[cv.length - 1];
  const mins = slides.reduce((m, x) => m + (x.data.tnote ? x.data.tnote.min : 0), 0), dur = 40 * cv.length;
  if (!(dur === 40 ? mins >= 30 && mins <= 45 : dur === 80 ? mins >= 60 && mins <= 88 : mins >= 90 && mins <= 130)) throw new Error(key + ' 발문 분 ' + mins + '/' + dur);
  LESSONS[key] = {
    meta: { grade: 4, subject: '사회', term: 2, unit: UNIT, unit_title: UT, n, covers: cv.length === 1 ? a + '차시' : cv.length === 2 ? a + '·' + c2 + '차시' : a + '~' + c2 + '차시', title: nm(s.title), goal: nm(s.title), std: s.std, duration_min: dur, lesson_format: t.fmt + ' · 2세대 19장(7요소)', theme: '곰이·펭이 산·들·바다·도시 탐사대', topic: s.topic, method: s.board, textbook: s.textbook, live_url: LIVE + s.file, source: 'grade4/semester2/social/' + DIR + '/' + s.file },
    slides, extras: ex
  };
});

const head = `/* ============================================================================
   4학년 2학기 사회 — 3단원 「다양한 환경과 삶의 모습」 케이티처 2세대 차시 데이터 (자기주도 l01~l12 · 지도서 1~16차시 × 19장)
   - 생성물: kedu/teacher/scripts/gen_g4s2_social_u3.js 가 만든다. 손으로 고치지 말고 생성기(T 표)를 고칠 것.
   - 키: window.LESSONS["u3_l{NN}"] = 지도서 차시 첫 번호 (l01 = 1·2 · l06 = 6·7 · l10 = 10·11 · l15 = 15·16 = 80분) · 주소 stage.html?g=4&s=social&t=2&u=3&l=u3_lNN · slug g4s2_social.
   - 계보: u3_l01 복습 = 4-2 사회 2단원 u2_l15 출구 퀴즈 · 이후 차시 복습 = 직전 차시 출구 퀴즈 · u3_l15 = 4-2 사회 끝(「이 단원을 마쳐요」).
   - 게이트(표준/gate_g4s2_social_u3.js)가 원문 계승·정답·판 표 대조(두 갈래·틈·덮기·세 단추·개발/되돌림·퍼즐·불빛·길·무언극·뒤집힘·접기·그물)·선행 용어·발문 분·실렌더를 전수 검사.
   ============================================================================ */
`;
fs.writeFileSync(OUT, head + '(function () {\n  if (!window.LESSONS) window.LESSONS = {};\n' + keys.map(k => '  window.LESSONS[' + JSON.stringify(k) + '] = ' + JSON.stringify(LESSONS[k]) + ';').join('\n') + '\n})();\n');
console.log('→', path.relative(process.cwd(), OUT), keys.length, '차시 키 ·', keys.reduce((a, k) => a + LESSONS[k].slides.length, 0), '장 ·', keys.reduce((a, k) => a + LESSONS[k].extras.length, 0), 'extras');
